SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 360, "#c7effb");
  let achados = 0;
  const esconderijos = SZGame2D.createGroup();
  const coelho = SZGame2D.createSprite({ x: 97, y: 142, w: 96, h: 112, image: "coelho" });
  const arbusto = SZGame2D.createSprite({ x: 72, y: 160, w: 150, h: 122, image: "arbusto" });
  SZGame2D.addToGroup(esconderijos, arbusto);
  const raposa = SZGame2D.createSprite({ x: 270, y: 142, w: 96, h: 112, image: "raposa" });
  const pedras = SZGame2D.createSprite({ x: 245, y: 160, w: 150, h: 122, image: "pedras" });
  SZGame2D.addToGroup(esconderijos, pedras);
  const coruja = SZGame2D.createSprite({ x: 443, y: 142, w: 96, h: 112, image: "coruja" });
  const flores = SZGame2D.createSprite({ x: 418, y: 160, w: 150, h: 122, image: "flores" });
  SZGame2D.addToGroup(esconderijos, flores);
  // Quando acontecer
  SZGame2D.onGroupClick(esconderijos, function (escolhido) {

  }, "cliqueSprite");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "jardim");
    SZGame2D.drawSprite(ctx, coelho);
    SZGame2D.drawSprite(ctx, raposa);
    SZGame2D.drawSprite(ctx, coruja);
    SZGame2D.drawGroup(ctx, esconderijos);
    SZGame2D.drawScore(ctx, "Achados:", achados, 18, 34, "#173844", 24);
    if (achados >= 3) {
      SZGame2D.drawLabel(ctx, "Você achou todo mundo!", 174, 72, "#173844", 27, "left");
    }
  }, "quadroDoJogo");
}, "__sz-project");
